from pathlib import Path

spec = importlib.util.spec_from_file_location("tool", Path(__file__).resolve().parents[2] / "b" / "tool.py")


def load(spec):
    def build():
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod
    return build()


